B.adz=new A.eF("voltage_drop","Volt\u2193","            SELECT (epoch_ms(ts) - epoch_ms(MIN(ts) OVER ())) / 1000.0 AS t\n            FROM (\n              SELECT ts,\n                voltage AS v,\n                AVG(voltage) OVER () AS mu,\n                STDDEV_SAMP(voltage) OVER () AS sd\n              FROM battery\n            )\n            WHERE sd > 0 AND (mu - v) / sd > 2.5\n            ORDER BY t\n            ")
