B.adB=new A.eF("climb_rate","Climb","            SELECT (epoch_ms(ts) - epoch_ms(MIN(ts) OVER ())) / 1000.0 AS t\n            FROM (\n              SELECT ts,\n                ABS(climb) AS v,\n                AVG(ABS(climb)) OVER () AS mu,\n                STDDEV_SAMP(ABS(climb)) OVER () AS sd\n              FROM vfr_hud\n            )\n            WHERE sd > 0 AND (v - mu) / sd > 2.5\n            ORDER BY t\n            ")
